// ==========================================
// 6. 3D ANTI-GRAVITY PERSPECTIVE TILT (LEAK-FREE)
// ==========================================
function rebind3DTilt() {
  const elements = document.querySelectorAll('[data-tilt]');
  elements.forEach(el => {
    if (el._tiltHandler) {
      el.removeEventListener('mousemove', el._tiltHandler);
      el.removeEventListener('mouseleave', el._tiltLeave);
    }

    el._tiltHandler = (e) => {
      const rect = el.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const centerX = rect.width / 2;
      const centerY = rect.height / 2;

      const rotateX = ((centerY - y) / centerY) * 7.5;
      const rotateY = ((x - centerX) / centerX) * 7.5;

      el.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateZ(10px)`;
    };

    el._tiltLeave = () => {
      el.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) translateZ(0px)';
    };

    el.addEventListener('mousemove', el._tiltHandler);
    el.addEventListener('mouseleave', el._tiltLeave);
  });
}

// ==========================================
// 7. TOAST NOTIFICATIONS
// ==========================================
function showPlatformToast(message, type = 'emerald') {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;
  toast.innerHTML = `<i class="fa-solid fa-circle-check text-emerald"></i><span>${message}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(15px)';
    setTimeout(() => toast.remove(), 300);
  }, 3600);
}

