#pragma once

#include <string>
#include <vector>
#include <optional>
#include <nlohmann/json.hpp>

namespace Nexus {

using json = nlohmann::json;

// 1. Transit Station Hub
struct Station {
    std::string id;
    std::string name;
    double x = 0.0;
    double y = 0.0;
    double z = 0.0;
    std::string zone;
    std::string icon;
};

inline void to_json(json& j, const Station& s) {
    j = json{
        {"id", s.id},
        {"name", s.name},
        {"x", s.x},
        {"y", s.y},
        {"z", s.z},
        {"zone", s.zone},
        {"icon", s.icon}
    };
}

inline void from_json(const json& j, Station& s) {
    j.at("id").get_to(s.id);
    j.at("name").get_to(s.name);
    j.at("x").get_to(s.x);
    j.at("y").get_to(s.y);
    j.at("z").get_to(s.z);
    j.at("zone").get_to(s.zone);
    if (j.contains("icon")) j.at("icon").get_to(s.icon);
}

// 2. Transit Corridor Segment
struct Corridor {
    std::string u;
    std::string v;
    double distance = 0.0;
};

inline void to_json(json& j, const Corridor& c) {
    j = json{
        {"u", c.u},
        {"v", c.v},
        {"distance", c.distance}
    };
}

inline void from_json(const json& j, Corridor& c) {
    j.at("u").get_to(c.u);
    j.at("v").get_to(c.v);
    j.at("distance").get_to(c.distance);
}

// 3. Commuter Passenger Request
struct Passenger {
    std::string id;
    std::string name;
    std::string pickup;
    std::string drop;
    std::string requestedAt;
    std::string status = "Pending Dispatch";
};

inline void to_json(json& j, const Passenger& p) {
    j = json{
        {"id", p.id},
        {"name", p.name},
        {"pickup", p.pickup},
        {"drop", p.drop},
        {"requestedAt", p.requestedAt},
        {"status", p.status}
    };
}

inline void from_json(const json& j, Passenger& p) {
    j.at("id").get_to(p.id);
    j.at("name").get_to(p.name);
    j.at("pickup").get_to(p.pickup);
    j.at("drop").get_to(p.drop);
    if (j.contains("requestedAt")) j.at("requestedAt").get_to(p.requestedAt);
    if (j.contains("status")) j.at("status").get_to(p.status);
}

// 4. Driver Partner
struct Driver {
    int id = 0;
    std::string name;
    std::string station;
    int seats = 0;
    int originalSeats = 0;
    int tripsCompleted = 0;
};

inline void to_json(json& j, const Driver& d) {
    j = json{
        {"id", d.id},
        {"name", d.name},
        {"station", d.station},
        {"seats", d.seats},
        {"originalSeats", d.originalSeats},
        {"tripsCompleted", d.tripsCompleted}
    };
}

inline void from_json(const json& j, Driver& d) {
    j.at("id").get_to(d.id);
    j.at("name").get_to(d.name);
    j.at("station").get_to(d.station);
    j.at("seats").get_to(d.seats);
    j.at("originalSeats").get_to(d.originalSeats);
    if (j.contains("tripsCompleted")) j.at("tripsCompleted").get_to(d.tripsCompleted);
}

// 5. Active Dispatched Shared Trip
struct Trip {
    std::string tripRef;
    Passenger passenger;
    int driverId = 0;
    std::string driverName;
    std::vector<std::string> corridorPath;
    double distance = 0.0;
    int time = 0;
    double fare = 0.0;
    double co2Saved = 0.0;
    int matchScore = 94;
    std::string dispatchedAt;
};

inline void to_json(json& j, const Trip& t) {
    j = json{
        {"tripRef", t.tripRef},
        {"passenger", t.passenger},
        {"driverId", t.driverId},
        {"driverName", t.driverName},
        {"corridorPath", t.corridorPath},
        {"distance", t.distance},
        {"time", t.time},
        {"fare", t.fare},
        {"co2Saved", t.co2Saved},
        {"matchScore", t.matchScore},
        {"dispatchedAt", t.dispatchedAt}
    };
}

inline void from_json(const json& j, Trip& t) {
    j.at("tripRef").get_to(t.tripRef);
    j.at("passenger").get_to(t.passenger);
    j.at("driverId").get_to(t.driverId);
    j.at("driverName").get_to(t.driverName);
    j.at("corridorPath").get_to(t.corridorPath);
    j.at("distance").get_to(t.distance);
    j.at("time").get_to(t.time);
    j.at("fare").get_to(t.fare);
    j.at("co2Saved").get_to(t.co2Saved);
    if (j.contains("matchScore")) j.at("matchScore").get_to(t.matchScore);
    if (j.contains("dispatchedAt")) j.at("dispatchedAt").get_to(t.dispatchedAt);
}

// 6. Audit Action Frame (LIFO Rollback Stack)
struct AuditAction {
    std::string type;
    std::string tripRef;
    int driverId = 0;
    Passenger passenger;
    Trip trip;
};

inline void to_json(json& j, const AuditAction& a) {
    j = json{
        {"type", a.type},
        {"tripRef", a.tripRef},
        {"driverId", a.driverId},
        {"passenger", a.passenger},
        {"trip", a.trip}
    };
}

// 7. Route Calculation Result
struct RouteResult {
    std::vector<std::string> path;
    double totalDist = 0.0;
    int estTime = 0;
    double co2Offset = 0.0;
    double fare = 0.0;
    int soloCarsSaved = 0;
};

inline void to_json(json& j, const RouteResult& r) {
    j = json{
        {"path", r.path},
        {"totalDist", r.totalDist},
        {"estTime", r.estTime},
        {"co2Offset", r.co2Offset},
        {"fare", r.fare},
        {"soloCarsSaved", r.soloCarsSaved}
    };
}

// 8. Eco Leaderboard Partner
struct EcoLeader {
    std::string name;
    int trips = 0;
    std::string co2;
    double rating = 5.0;
    std::string badge;
};

inline void to_json(json& j, const EcoLeader& e) {
    j = json{
        {"name", e.name},
        {"trips", e.trips},
        {"co2", e.co2},
        {"rating", e.rating},
        {"badge", e.badge}
    };
}

} // namespace Nexus

#pragma once

#include "Models.hpp"
#include <string>
#include <vector>
#include <array>
#include <queue>
#include <deque>
#include <optional>
#include <mutex>
#include <memory>
#include <unordered_map>

namespace Nexus {

class NexusEngine {
public:
    static NexusEngine& getInstance() {
        static NexusEngine instance;
        return instance;
    }

    // Network Topology
    std::vector<Station> getStations() const;
    std::vector<Corridor> getCorridors() const;

    // Dijkstra Eco-Pathfinding
    RouteResult findOptimalEcoRoute(const std::string& startId, const std::string& endId, int commuterDensity = 2);

    // Commuter Request FIFO Queue
    Passenger submitRideRequest(const std::string& name, const std::string& pickup, const std::string& drop);
    std::optional<Passenger> dequeueNextRequest();
    std::vector<Passenger> getDispatchQueue() const;

    // Fixed 5-Slot Priority Standby Ring Buffer
    struct StandbyStatus {
        int capacity = 5;
        int count = 0;
        int front = 0;
        int rear = 0;
        std::vector<std::optional<Passenger>> slots;
    };

    bool pushToStandby(const Passenger& p, std::string& errorMsg);
    std::optional<Passenger> popFromStandby(std::string& errorMsg);
    StandbyStatus getStandbyStatus() const;

    // Driver Fleet Management
    Driver onboardDriver(const std::string& name, const std::string& station, int seats);
    std::vector<Driver> getFleet() const;
    std::optional<Driver> getDriverById(int id) const;

    // Active Shared Trips & Route Matching
    Trip dispatchSharedTrip(const Passenger& passenger, int driverId, int matchScore = 94);
    std::optional<Trip> autoMatchTrip(int matchScore = 94, std::string* errorMsg = nullptr);
    std::vector<Trip> getActiveTrips() const;
    std::optional<Trip> getTripByRef(const std::string& ref) const;
    bool completeOrCancelTrip(const std::string& tripRef);

    // Identity Verification (Driver ID or Booking Reference)
    json verifyRecord(const std::string& query) const;

    // Reversal LIFO Audit Stack (Rollback Engine)
    struct ReversalResult {
        bool success = false;
        std::string message;
        std::optional<AuditAction> action;
        std::optional<Driver> driver;
    };
    ReversalResult revertLatestConfirmation();
    std::vector<AuditAction> getAuditHistory() const;

    // Sustainability Analytics
    json getSustainabilityMetrics() const;
    std::vector<EcoLeader> getLeaderboard() const;

    // One-Click Rush-Hour Simulation Scenario
    json loadRushHourDemo();

    // Reset Engine State
    void reset();

private:
    NexusEngine();
    ~NexusEngine() = default;
    NexusEngine(const NexusEngine&) = delete;
    NexusEngine& operator=(const NexusEngine&) = delete;

    mutable std::mutex mtx_;

    // Graph Network
    std::vector<Station> stations_;
    std::vector<Corridor> corridors_;
    std::unordered_map<std::string, std::vector<std::pair<std::string, double>>> adjList_;

    // Commuter FIFO Queue
    std::deque<Passenger> dispatchQueue_;

    // 5-Slot Priority Standby Circular Ring Buffer
    static constexpr size_t STANDBY_CAP = 5;
    std::array<std::optional<Passenger>, STANDBY_CAP> standbyLounge_;
    size_t standbyFront_ = 0;
    size_t standbyRear_ = 0;
    size_t standbyCount_ = 0;

    // Driver Fleet & Active Trips
    std::vector<Driver> fleetPartners_;
    std::vector<Trip> activeTrips_;

    // LIFO Reversal Audit Log
    std::vector<AuditAction> reversalAuditLog_;

    // Leaderboard
    std::vector<EcoLeader> leaderboard_;

    // ID Counters
    int nextDriverId_ = 101;
    int nextBookingRef_ = 501;
    int nextPassengerId_ = 201;

    void initDefaultNetwork();
    std::string getCurrentTimestamp() const;
};

} // namespace Nexus

#include "NexusEngine.hpp"
#include <chrono>
#include <ctime>
#include <iomanip>
#include <sstream>
#include <cmath>
#include <algorithm>
#include <cctype>

namespace Nexus {

NexusEngine::NexusEngine() {
    initDefaultNetwork();
}

void NexusEngine::initDefaultNetwork() {
    stations_ = {
        {"ALPHA", "Tech Park Alpha", -160.0, -70.0, 20.0, "North Industrial", "fa-microchip"},
        {"HARBOR", "Bayfront Terminal", -80.0, 110.0, -15.0, "Maritime District", "fa-anchor"},
        {"METRO", "Central Financial Core", 0.0, 0.0, 40.0, "Downtown Metro", "fa-building-columns"},
        {"SKYPORT", "AeroPort Interchange", 130.0, -90.0, 30.0, "Aviation Corridor", "fa-plane-departure"},
        {"QUANTUM", "Green Innovation Campus", 90.0, 100.0, -10.0, "Eco District", "fa-seedling"},
        {"HORIZON", "Waterfront Marina", 200.0, 30.0, 5.0, "East Residential", "fa-water"}
    };

    corridors_ = {
        {"ALPHA", "METRO", 8.2},
        {"ALPHA", "HARBOR", 11.5},
        {"HARBOR", "METRO", 6.4},
        {"HARBOR", "QUANTUM", 13.8},
        {"METRO", "SKYPORT", 9.6},
        {"METRO", "QUANTUM", 7.1},
        {"SKYPORT", "HORIZON", 8.8},
        {"QUANTUM", "HORIZON", 10.4}
    };

    adjList_.clear();
    for (const auto& s : stations_) {
        adjList_[s.id] = {};
    }
    for (const auto& c : corridors_) {
        adjList_[c.u].push_back({c.v, c.distance});
        adjList_[c.v].push_back({c.u, c.distance});
    }

    leaderboard_ = {
        {"Kaelen Chen", 42, "168.4 kg", 4.98, "Carbon Crusader"},
        {"Elena Rostova", 37, "142.1 kg", 4.95, "5-Star Commute"},
        {"Marcus Vance", 31, "128.0 kg", 4.92, "Zero-Emission Pioneer"},
        {"Siddharth Rao", 28, "115.6 kg", 4.89, "Master Navigator"}
    };

    standbyLounge_.fill(std::nullopt);
    standbyFront_ = 0;
    standbyRear_ = 0;
    standbyCount_ = 0;
}

std::string NexusEngine::getCurrentTimestamp() const {
    auto now = std::chrono::system_clock::now();
    std::time_t in_time_t = std::chrono::system_clock::to_time_t(now);
    std::tm buf{};
#if defined(_WIN32)
    localtime_s(&buf, &in_time_t);
#else
    localtime_r(&in_time_t, &buf);
#endif
    std::ostringstream ss;
    ss << std::put_time(&buf, "%H:%M");
    return ss.str();
}

