76:   findOptimalEcoRoute(startId, endId) {
77:     const adj = {};
78:     TRANSIT_STATIONS.forEach(s => { adj[s.id] = []; });
79:     TRANSIT_CORRIDORS.forEach(c => {
80:       adj[c.u].push({ node: c.v, distance: c.distance });
81:       adj[c.v].push({ node: c.u, distance: c.distance });
82:     });
83: 
84:     const dist = {};
85:     const prev = {};
86:     TRANSIT_STATIONS.forEach(s => {
87:       dist[s.id] = Infinity;
88:       prev[s.id] = null;
89:     });
90: 
91:     dist[startId] = 0;
92:     const activeCorridors = [[0, startId]];
93: 
94:     while (activeCorridors.length > 0) {
95:       activeCorridors.sort((a, b) => a[0] - b[0]);
96:       const [d, u] = activeCorridors.shift();
97: 
98:       if (u === endId) break;
99:       if (d > dist[u]) continue;
100: 
101:       for (const edge of adj[u]) {
102:         const v = edge.node;
103:         const newDist = dist[u] + edge.distance;
104:         if (newDist < dist[v]) {
105:           dist[v] = newDist;
106:           prev[v] = u;
107:           activeCorridors.push([newDist, v]);
108:         }
109:       }
110:     }
111: 
112:     const path = [];
113:     let curr = endId;
114:     if (dist[endId] !== Infinity) {
115:       while (curr) {
116:         path.unshift(curr);
117:         curr = prev[curr];
118:       }
119:     }
120: 
121:     const totalDist = dist[endId] === Infinity ? 0 : parseFloat(dist[endId].toFixed(1));
122:     const estTime = Math.round(totalDist * 2.2);
123:     const baseCO2 = totalDist * 0.171;
124:     const co2Offset = parseFloat((baseCO2 * (0.8 + this.commuterDensity * 0.4)).toFixed(2));
125: 
126:     const baseTripCost = 4.0 + totalDist * 1.5;
127:     const pooledFare = parseFloat(((baseTripCost * (1 + (this.commuterDensity - 1) * 0.25)) / this.commuterDensity).toFixed(2));
128: 
129:     return {
130:       path,
131:       totalDist,
132:       estTime,
133:       co2Offset,
134:       fare: pooledFare,
135:       soloCarsSaved: Math.max(0, this.commuterDensity - 1)
136:     };
137:   }
