291:   initParticles() {
292:     this.particles = [];
293:     for (let i = 0; i < this.numParticles; i++) {
294:       this.particles.push({
295:         x: Math.random() * this.width,
296:         y: Math.random() * this.height,
297:         size: Math.random() * 8 + 4,
298:         speedY: -(Math.random() * 0.45 + 0.15),
299:         speedX: Math.sin(Math.random() * Math.PI) * 0.25,
300:         rotation: Math.random() * Math.PI * 2,
301:         rotSpeed: (Math.random() - 0.5) * 0.015,
