308:   animate() {
309:     this.ctx.clearRect(0, 0, this.width, this.height);
310: 
311:     this.particles.forEach(p => {
312:       p.y += p.speedY;
313:       p.x += p.speedX + Math.sin(p.y * 0.01) * 0.2;
314:       p.rotation += p.rotSpeed;
315: 
316:       // Wrap around
317:       if (p.y < -20) {
318:         p.y = this.height + 20;
319:         p.x = Math.random() * this.width;
320:       }
321:       if (p.x < -20) p.x = this.width + 20;
322:       if (p.x > this.width + 20) p.x = -20;
323: 
324:       this.ctx.save();
325:       this.ctx.translate(p.x, p.y);
326:       this.ctx.rotate(p.rotation);
327: 
328:       if (p.type === 'leaf') {
329:         // Draw delicate eco-leaf
330:         this.ctx.fillStyle = `rgba(5, 150, 105, ${p.opacity * 0.55})`;
331:         this.ctx.beginPath();
332:         this.ctx.ellipse(0, 0, p.size, p.size * 0.55, 0, 0, Math.PI * 2);
333:         this.ctx.fill();
334: 
335:         // Leaf stem line
336:         this.ctx.strokeStyle = `rgba(5, 150, 105, ${p.opacity * 0.7})`;
337:         this.ctx.lineWidth = 0.8;
338:         this.ctx.beginPath();
339:         this.ctx.moveTo(-p.size, 0);
340:         this.ctx.lineTo(p.size, 0);
341:         this.ctx.stroke();
342:       } else {
343:         // Light glowing electric energy node
344:         this.ctx.fillStyle = `rgba(37, 99, 235, ${p.opacity * 0.45})`;
345:         this.ctx.beginPath();
346:         this.ctx.arc(0, 0, p.size * 0.4, 0, Math.PI * 2);
347:         this.ctx.fill();
348:       }
349: 
350:       this.ctx.restore();
351:     });
352: 
353:     requestAnimationFrame(() => this.animate());
354:   }
355: }
