400:     this.canvas.addEventListener('mousedown', (e) => {
401:       this.isDragging = true;
402:       this.lastMouseX = e.clientX;
403:       this.lastMouseY = e.clientY;
404:     });
405: 
406:     window.addEventListener('mouseup', () => {
407:       this.isDragging = false;
408:     });
409: 
410:     this.canvas.addEventListener('mousemove', (e) => {
411:       if (this.isDragging) {
412:         const deltaX = e.clientX - this.lastMouseX;
413:         const deltaY = e.clientY - this.lastMouseY;
414:         this.rotY += deltaX * 0.007;
415:         this.rotX += deltaY * 0.007;
416:         this.rotX = Math.max(0.12, Math.min(1.2, this.rotX));
417:         this.lastMouseX = e.clientX;
418:         this.lastMouseY = e.clientY;
419:       }
420:       this.checkHover(e);
421:     });
