430:   checkHover(e) {
431:     const rect = this.canvas.getBoundingClientRect();
432:     const mouseX = e.clientX - rect.left;
433:     const mouseY = e.clientY - rect.top;
434: 
435:     let found = null;
436:     TRANSIT_STATIONS.forEach(s => {
437:       const p = this.project(s.x, s.y, s.z);
438:       const dist = Math.hypot(p.x - mouseX, p.y - mouseY);
439:       if (dist < 22) {
440:         found = s;
441:       }
442:     });
443: 
444:     this.hoveredStation = found;
445:     const hud = document.getElementById('map-hud-overlay');
446:     if (hud) {
447:       if (found) {
448:         hud.innerHTML = `<span class="text-emerald font-bold">📍 ${found.name}</span> &bull; Transit Zone: ${found.zone} &bull; Elevation: +${found.z}m`;
449:       } else {
