451:       }
452:     }
453:   }
454: 
455:   project(x, y, z) {
456:     const cosY = Math.cos(this.rotY);
457:     const sinY = Math.sin(this.rotY);
458:     const x1 = x * cosY + z * sinY;
459:     const z1 = -x * sinY + z * cosY;
460: 
461:     const cosX = Math.cos(this.rotX);
462:     const sinX = Math.sin(this.rotX);
463:     const y2 = y * cosX - z1 * sinX;
464:     const z2 = y * sinX + z1 * cosX;
465: 
466:     const cameraDist = 440;
467:     const fov = cameraDist / (cameraDist + z2);
468: 
469:     const screenX = this.width / 2 + x1 * fov * this.scale;
470:     const screenY = this.height / 2 + y2 * fov * this.scale;
471: 
472:     return { x: screenX, y: screenY, scale: fov, z: z2 };
473:   }
474: 
475:   setActivePath(path) {
476:     this.activeCorridorPath = path;
477:     this.carProgress = 0;
478:     this.isCarDriving = path && path.length > 1;
479:   }
480: 
481:   startCarSimulation() {
482:     if (this.activeCorridorPath && this.activeCorridorPath.length > 1) {
483:       this.carProgress = 0;
484:       this.isCarDriving = true;
485:     }
486:   }
487: 
488:   resetCamera() {
489:     this.rotX = 0.45;
490:     this.rotY = -0.32;
491:     this.scale = 1.08;
492:   }
493: 
494:   animate() {
495:     this.flowDashOffset -= 0.6;
496:     this.render();
497: 
498:     // Advance transit vehicle along path
499:     if (this.isCarDriving && this.activeCorridorPath.length > 1) {
500:       this.carProgress += this.carSpeed;
501:       if (this.carProgress >= this.activeCorridorPath.length - 1) {
502:         this.carProgress = 0; // Loop or stop
503:       }
504:     }
505: 
506:     requestAnimationFrame(() => this.animate());
507:   }
