509:   render() {
510:     const ctx = this.ctx;
511:     ctx.clearRect(0, 0, this.width, this.height);
512: 
513:     this.drawGroundGrid();
514: 
515:     // Draw Corridors
516:     TRANSIT_CORRIDORS.forEach(corridor => {
517:       const uStation = TRANSIT_STATIONS.find(s => s.id === corridor.u);
518:       const vStation = TRANSIT_STATIONS.find(s => s.id === corridor.v);
519:       const p1 = this.project(uStation.x, uStation.y, uStation.z);
520:       const p2 = this.project(vStation.x, vStation.y, vStation.z);
521: 
522:       let isPath = false;
523:       let pathDirection = 0; // 1: u->v, -1: v->u
524: 
525:       for (let i = 0; i < this.activeCorridorPath.length - 1; i++) {
526:         const a = this.activeCorridorPath[i];
527:         const b = this.activeCorridorPath[i + 1];
528:         if (a === corridor.u && b === corridor.v) {
529:           isPath = true;
530:           pathDirection = 1;
531:           break;
532:         } else if (a === corridor.v && b === corridor.u) {
533:           isPath = true;
534:           pathDirection = -1;
535:           break;
536:         }
537:       }
538: 
539:       ctx.save();
540:       ctx.beginPath();
541:       ctx.moveTo(p1.x, p1.y);
542:       ctx.lineTo(p2.x, p2.y);
543: 
544:       if (isPath) {
545:         // Base route vector line
546:         ctx.strokeStyle = '#2563EB';
547:         ctx.lineWidth = 4.5;
548:         ctx.stroke();
549: 
550:         // Directional Flow Animation (Chevrons / dashed energy pulses)
551:         ctx.save();
552:         ctx.beginPath();
553:         const startP = pathDirection === 1 ? p1 : p2;
554:         const endP = pathDirection === 1 ? p2 : p1;
555:         ctx.moveTo(startP.x, startP.y);
556:         ctx.lineTo(endP.x, endP.y);
557:         ctx.strokeStyle = '#60A5FA';
558:         ctx.lineWidth = 2.5;
559:         ctx.setLineDash([8, 12]);
560:         ctx.lineDashOffset = this.flowDashOffset;
561:         ctx.stroke();
562:         ctx.restore();
563:       } else {
564:         ctx.strokeStyle = '#CBD5E1';
565:         ctx.lineWidth = 2;
566:         ctx.stroke();
567:       }
568:       ctx.restore();
569: 
570:       // Corridor Distance Tag
571:       const midX = (p1.x + p2.x) / 2;
572:       const midY = (p1.y + p2.y) / 2;
573:       ctx.save();
574:       ctx.fillStyle = isPath ? '#2563EB' : '#FFFFFF';
575:       ctx.strokeStyle = isPath ? '#1D4ED8' : '#CBD5E1';
576:       ctx.lineWidth = 1;
577:       ctx.beginPath();
578:       ctx.roundRect(midX - 16, midY - 9, 32, 18, 4);
579:       ctx.fill();
580:       ctx.stroke();
581: 
582:       ctx.fillStyle = isPath ? '#FFFFFF' : '#475569';
583:       ctx.font = 'bold 9px "JetBrains Mono"';
584:       ctx.textAlign = 'center';
585:       ctx.textBaseline = 'middle';
586:       ctx.fillText(`${corridor.distance}km`, midX, midY);
587:       ctx.restore();
588:     });
589: 
590:     // Draw Stations (Sorted by Z for depth)
591:     const sorted = [...TRANSIT_STATIONS].map(s => ({
592:       station: s,
593:       proj: this.project(s.x, s.y, s.z)
594:     })).sort((a, b) => b.proj.z - a.proj.z);
595: 
596:     sorted.forEach(({ station, proj }) => {
597:       const isPath = this.activeCorridorPath.includes(station.id);
598:       const isHovered = this.hoveredStation && this.hoveredStation.id === station.id;
599: 
600:       ctx.save();
601: 
602:       // Floor Shadow
603:       const floorProj = this.project(station.x, station.y, -30);
604:       ctx.beginPath();
605:       ctx.ellipse(floorProj.x, floorProj.y, 14 * proj.scale, 7 * proj.scale, 0, 0, Math.PI * 2);
606:       ctx.fillStyle = 'rgba(15, 23, 42, 0.08)';
607:       ctx.fill();
608: 
609:       // Elevation Stem
610:       ctx.beginPath();
611:       ctx.moveTo(floorProj.x, floorProj.y);
612:       ctx.lineTo(proj.x, proj.y);
613:       ctx.strokeStyle = isPath ? 'rgba(5, 150, 105, 0.6)' : '#CBD5E1';
614:       ctx.lineWidth = 1.5;
615:       ctx.setLineDash([2, 3]);
616:       ctx.stroke();
617:       ctx.setLineDash([]);
618: 
619:       // Station Circle
620:       ctx.beginPath();
621:       const radius = (isHovered ? 14 : 11) * proj.scale;
622:       ctx.arc(proj.x, proj.y, radius, 0, Math.PI * 2);
623: 
624:       if (isPath) {
625:         ctx.fillStyle = '#059669';
626:         ctx.shadowColor = 'rgba(5, 150, 105, 0.4)';
627:         ctx.shadowBlur = 14;
628:       } else if (isHovered) {
629:         ctx.fillStyle = '#2563EB';
630:         ctx.shadowColor = 'rgba(37, 99, 235, 0.4)';
631:         ctx.shadowBlur = 12;
632:       } else {
633:         ctx.fillStyle = '#FFFFFF';
634:         ctx.strokeStyle = '#059669';
635:         ctx.lineWidth = 2.5;
636:         ctx.stroke();
637:       }
638:       ctx.fill();
639:       ctx.restore();
640: 
641:       // Station Label & Zone
642:       ctx.save();
643:       ctx.font = '600 11px "Inter"';
644:       ctx.fillStyle = isPath ? '#059669' : '#0F172A';
645:       ctx.textAlign = 'center';
646:       ctx.fillText(station.name, proj.x, proj.y - 18 * proj.scale);
647:       ctx.font = '500 9px "JetBrains Mono"';
648:       ctx.fillStyle = '#64748B';
649:       ctx.fillText(station.zone, proj.x, proj.y + 20 * proj.scale);
650:       ctx.restore();
651:     });
