659:   drawAnimatedCar() {
660:     const ctx = this.ctx;
661:     const segmentIndex = Math.floor(this.carProgress);
662:     const segmentT = this.carProgress - segmentIndex;
663: 
664:     const fromId = this.activeCorridorPath[segmentIndex];
665:     const toId = this.activeCorridorPath[segmentIndex + 1];
666: 
667:     if (!fromId || !toId) return;
668: 
669:     const s1 = TRANSIT_STATIONS.find(s => s.id === fromId);
670:     const s2 = TRANSIT_STATIONS.find(s => s.id === toId);
671: 
672:     // Interpolate 3D coordinates
673:     const curX = s1.x + (s2.x - s1.x) * segmentT;
674:     const curY = s1.y + (s2.y - s1.y) * segmentT;
675:     const curZ = s1.z + (s2.z - s1.z) * segmentT;
676: 
677:     const carProj = this.project(curX, curY, curZ);
678: 
679:     // Calculate heading angle
680:     const p1 = this.project(s1.x, s1.y, s1.z);
681:     const p2 = this.project(s2.x, s2.y, s2.z);
682:     const heading = Math.atan2(p2.y - p1.y, p2.x - p1.x);
683: 
684:     ctx.save();
685:     ctx.translate(carProj.x, carProj.y);
686:     ctx.rotate(heading);
687: 
688:     // Glowing Headlight Beams
689:     ctx.beginPath();
690:     ctx.moveTo(12 * carProj.scale, -4 * carProj.scale);
691:     ctx.lineTo(26 * carProj.scale, -12 * carProj.scale);
692:     ctx.lineTo(26 * carProj.scale, 12 * carProj.scale);
693:     ctx.lineTo(12 * carProj.scale, 4 * carProj.scale);
694:     ctx.closePath();
695:     const lightGrad = ctx.createLinearGradient(12 * carProj.scale, 0, 26 * carProj.scale, 0);
696:     lightGrad.addColorStop(0, 'rgba(32, 201, 176, 0.45)');
697:     lightGrad.addColorStop(1, 'rgba(32, 201, 176, 0)');
698:     ctx.fillStyle = lightGrad;
699:     ctx.fill();
700: 
701:     // Electric Vehicle Chassis
702:     ctx.beginPath();
703:     ctx.roundRect(-10 * carProj.scale, -6 * carProj.scale, 20 * carProj.scale, 12 * carProj.scale, 4 * carProj.scale);
704:     ctx.fillStyle = '#059669';
705:     ctx.fill();
706:     ctx.strokeStyle = '#FFFFFF';
707:     ctx.lineWidth = 1.5;
708:     ctx.stroke();
709: 
710:     // Windshield
711:     ctx.beginPath();
712:     ctx.roundRect(0, -4 * carProj.scale, 5 * carProj.scale, 8 * carProj.scale, 2 * carProj.scale);
713:     ctx.fillStyle = '#93C5FD';
714:     ctx.fill();
715: 
716:     // Headlight bulbs
717:     ctx.fillStyle = '#FEF08A';
718:     ctx.fillRect(8 * carProj.scale, -5 * carProj.scale, 2 * carProj.scale, 2 * carProj.scale);
719:     ctx.fillRect(8 * carProj.scale, 3 * carProj.scale, 2 * carProj.scale, 2 * carProj.scale);
720: 
721:     ctx.restore();
722:   }
