724:   drawGroundGrid() {
725:     const ctx = this.ctx;
726:     const size = 220;
727:     const step = 44;
728:     const floorZ = -30;
729: 
730:     ctx.save();
731:     ctx.strokeStyle = 'rgba(203, 213, 225, 0.6)';
732:     ctx.lineWidth = 1;
733: 
734:     for (let i = -size; i <= size; i += step) {
735:       const p1 = this.project(i, -size, floorZ);
736:       const p2 = this.project(i, size, floorZ);
737:       ctx.beginPath();
738:       ctx.moveTo(p1.x, p1.y);
739:       ctx.lineTo(p2.x, p2.y);
740:       ctx.stroke();
741: 
742:       const p3 = this.project(-size, i, floorZ);
743:       const p4 = this.project(size, i, floorZ);
744:       ctx.beginPath();
745:       ctx.moveTo(p3.x, p3.y);
746:       ctx.lineTo(p4.x, p4.y);
747:       ctx.stroke();
748:     }
749:     ctx.restore();
750:   }
