882: // --- Priority Standby Lounge ---
883: function renderStandbyLounge() {
884:   const ring = document.getElementById('standby-ring');
885:   const counter = document.getElementById('standby-slot-counter');
886:   const pill = document.getElementById('standby-status-pill');
887:   if (!ring || !counter || !pill) return;
888: 
889:   counter.textContent = `${engine.standbyCount} / ${engine.standbyCap}`;
890:   pill.textContent = `Available Slots: ${engine.standbyCap - engine.standbyCount} / ${engine.standbyCap}`;
891: 
892:   ring.innerHTML = '';
893:   const total = engine.standbyCap;
894:   const radius = 90;
895: 
896:   for (let i = 0; i < total; i++) {
897:     const angle = (i * 2 * Math.PI) / total - Math.PI / 2;
898:     const x = Math.round(radius * Math.cos(angle) + 105);
899:     const y = Math.round(radius * Math.sin(angle) + 105);
900: 
901:     const isOccupied = engine.standbyLounge[i] !== null;
902:     const isActivePointer = i === engine.standbyFront && engine.standbyCount > 0;
903: 
904:     const slotEl = document.createElement('div');
905:     slotEl.className = `standby-slot ${isOccupied ? 'occupied' : ''} ${isActivePointer ? 'is-active-pointer' : ''}`;
906:     slotEl.style.left = `${x}px`;
907:     slotEl.style.top = `${y}px`;
908: 
909:     const passenger = engine.standbyLounge[i];
910:     slotEl.innerHTML = `
911:       <div class="font-bold">SLOT ${i + 1}</div>
912:       <div class="text-[9px] truncate max-w-[42px]">${passenger ? passenger.name.split(' ')[0] : 'FREE'}</div>
913:     `;
914:     slotEl.title = passenger ? `Standby: ${passenger.name} (${passenger.pickup} -> ${passenger.drop})` : `Slot ${i + 1}: Empty`;
915:     ring.appendChild(slotEl);
916:   }
917: }
