1001: // --- Transit Hierarchy Canvas ---
1002: function renderTransitHierarchyCanvas() {
1003:   const canvas = document.getElementById('trip-hierarchy-canvas');
1004:   if (!canvas) return;
1005:   const ctx = canvas.getContext('2d');
1006:   const countPill = document.getElementById('registry-count-pill');
1007: 
1008:   countPill.textContent = `${engine.activeTrips.length} Active Trips`;
1009:   ctx.clearRect(0, 0, canvas.width, canvas.height);
1010: 
1011:   if (engine.activeTrips.length === 0) {
1012:     ctx.fillStyle = '#64748B';
1013:     ctx.font = '11px "Inter"';
1014:     ctx.textAlign = 'center';
1015:     ctx.fillText('Transit Dispatch Registry Ready. Active shared trips will display here.', canvas.width / 2, canvas.height / 2);
1016:     return;
1017:   }
1018: 
1019:   // Draw Root Hub
1020:   const rootX = canvas.width / 2;
1021:   const rootY = 24;
1022: 
1023:   ctx.beginPath();
1024:   ctx.arc(rootX, rootY, 14, 0, Math.PI * 2);
1025:   ctx.fillStyle = '#FFFFFF';
1026:   ctx.strokeStyle = '#059669';
1027:   ctx.lineWidth = 2.5;
1028:   ctx.fill();
1029:   ctx.stroke();
1030: 
1031:   ctx.fillStyle = '#059669';
1032:   ctx.font = 'bold 9px "Inter"';
1033:   ctx.textAlign = 'center';
1034:   ctx.textBaseline = 'middle';
1035:   ctx.fillText('NEXUS', rootX, rootY);
1036: 
1037:   // Draw Branches
1038:   const count = engine.activeTrips.length;
1039:   const spacing = Math.min(80, (canvas.width - 60) / Math.max(count, 1));
1040:   const startX = rootX - ((count - 1) * spacing) / 2;
1041: 
1042:   engine.activeTrips.forEach((trip, idx) => {
1043:     const nodeX = startX + idx * spacing;
1044:     const nodeY = 110;
1045: 
1046:     ctx.beginPath();
1047:     ctx.moveTo(rootX, rootY + 14);
1048:     ctx.lineTo(nodeX, nodeY - 14);
1049:     ctx.strokeStyle = '#CBD5E1';
1050:     ctx.lineWidth = 1.5;
1051:     ctx.stroke();
1052: 
1053:     ctx.beginPath();
1054:     ctx.arc(nodeX, nodeY, 13, 0, Math.PI * 2);
1055:     ctx.fillStyle = '#FFFFFF';
1056:     ctx.strokeStyle = '#2563EB';
1057:     ctx.lineWidth = 2;
1058:     ctx.shadowColor = 'rgba(37, 99, 235, 0.2)';
1059:     ctx.shadowBlur = 6;
1060:     ctx.fill();
1061:     ctx.stroke();
1062:     ctx.shadowBlur = 0;
1063: 
1064:     ctx.fillStyle = '#1E293B';
1065:     ctx.font = 'bold 8px "JetBrains Mono"';
1066:     ctx.textAlign = 'center';
1067:     ctx.fillText(trip.tripRef.replace('NX-', ''), nodeX, nodeY);
1068: 
1069:     ctx.fillStyle = '#059669';
1070:     ctx.font = '500 8px "Inter"';
1071:     ctx.fillText(trip.passenger.name.split(' ')[0], nodeX, nodeY + 22);
1072:   });
1073: }
