  --electric-border: #BFDBFE;
  --electric-glow: rgba(37, 99, 235, 0.25);

  --amber: #D97706;
  --amber-light: #FFFBEB;
  --amber-border: #FDE68A;

  --purple: #7C3AED;
  --purple-light: #F5F3FF;
  --purple-border: #DDD6FE;

  --rose: #E11D48;
  --rose-light: #FFF1F2;
  --rose-border: #FECDD3;

  --slate-900: #0F172A;
  --slate-800: #1E293B;
  --slate-700: #334155;
  --slate-600: #475569;
  --slate-500: #64748B;
