  font-family: var(--font-mono);
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
}

.standby-slot.occupied {
  background: var(--amber-light);
  border-color: var(--amber);
  color: var(--amber);
  box-shadow: 0 4px 12px rgba(217, 119, 6, 0.2);
}

.standby-slot.is-active-pointer {
  border-color: var(--emerald);
  background: var(--emerald-light);
  color: var(--emerald);
  box-shadow: 0 0 0 3px rgba(5, 150, 105, 0.2);
}

/* --------------------------------------------------------------------------
   TAB 3: DRIVER FLEET & DISPATCH CONSOLE
   -------------------------------------------------------------------------- */
.view-grid-fleet {
  display: grid;
  grid-template-columns: 1.1fr 1.9fr;
  gap: 1.5rem;
}

.fleet-onboarding-card {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* Vehicle Chassis Blueprint Diagram */
.vehicle-blueprint-box {
  background: #F8FAFC;
  border: 1px solid var(--slate-200);
  border-radius: 14px;
  padding: 1.15rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.vehicle-blueprint-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--slate-700);
}

.vehicle-chassis-diagram {
  width: 170px;
  height: 220px;
  margin: 0 auto;
  border: 2px solid var(--slate-300);
  border-radius: 40px 40px 24px 24px;
  background: #FFFFFF;
  position: relative;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
  padding: 1.25rem 0.75rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.chassis-row {
  display: flex;
  justify-content: space-around;
  gap: 0.5rem;
}

.vehicle-seat {
  width: 58px;
  height: 64px;
  border-radius: 10px;
  border: 1.5px solid var(--slate-200);
  background: #FFFFFF;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  font-size: 0.65rem;
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--slate-600);
  cursor: pointer;
  transition: all 0.2s ease;
}

.vehicle-seat:hover {
  border-color: var(--emerald);
  transform: translateY(-2px);
}

.vehicle-seat.driver-locked {
  background: #F1F5F9;
  border-color: var(--slate-300);
  color: var(--slate-700);
  cursor: default;
}

.vehicle-seat.active-seat {
  background: var(--emerald-light);
  border-color: var(--emerald);
  color: var(--emerald);
  box-shadow: 0 4px 10px var(--emerald-glow);
}

.vehicle-seat.reserved-seat {
  background: var(--rose-light);
  border-color: var(--rose-border);
  color: var(--rose);
}

/* Fleet Directory & Active Trips Column */
.fleet-operations-column {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.fleet-stream-container {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
}

.driver-partner-card {
  min-width: 220px;
  background: #FFFFFF;
  border: 1px solid var(--slate-200);
  border-radius: 12px;
  padding: 0.9rem 1.1rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  flex-shrink: 0;
}

.card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.driver-id-badge {
  font-size: 0.65rem;
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--slate-500);
}

.seat-counter-pill {
  font-size: 0.65rem;
  font-weight: 700;
  background: var(--emerald-light);
  color: var(--emerald);
  border: 1px solid var(--emerald-border);
  padding: 0.15rem 0.45rem;
  border-radius: 9999px;
}

.driver-name {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--slate-900);
}

.driver-corridor {
  font-size: 0.75rem;
  color: var(--slate-600);
}

.fleet-pointer {
  display: flex;
  align-items: center;
  color: var(--slate-400);
}

/* Active Shared Trips Console */
.active-trips-stream {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1rem;
}

.shared-trip-card {
  background: #FFFFFF;
  border: 1px solid var(--slate-200);
  border-radius: 12px;
  padding: 1rem 1.15rem;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  position: relative;
}

.route-match-badge {
  font-size: 0.65rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 6px;
  background: var(--electric-light);
  color: var(--electric);
  border: 1px solid var(--electric-border);
}

.trip-ref {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--slate-500);
}

.btn-cancel-trip {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #F1F5F9;
  border: none;
  color: var(--slate-400);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 0.7rem;
  transition: all 0.2s ease;
}
.btn-cancel-trip:hover {
  background: var(--rose-light);
  color: var(--rose);
}

/* Search & Identity Verification Bar */
.verification-bar-card {
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.search-input-row {
  display: flex;
  gap: 0.75rem;
}

.verification-result-box {
  background: #F8FAFC;
  border: 1px dashed var(--slate-200);
  border-radius: 10px;
  padding: 0.75rem 1rem;
  display: flex;
  align-items: center;
}

/* --------------------------------------------------------------------------
   TAB 4: CITY SUSTAINABILITY ANALYTICS
   -------------------------------------------------------------------------- */
.view-grid-analytics {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.analytics-metrics-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.25rem;
}

.analytics-kpi-card {
  background: #FFFFFF;
  border: 1px solid var(--slate-200);
  border-radius: 14px;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.analytics-two-col {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 1.5rem;
}

.audit-history-list {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  max-height: 280px;
  overflow-y: auto;
}

.audit-entry {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.65rem 0.85rem;
  background: #F8FAFC;
  border: 1px solid var(--slate-200);
  border-radius: 8px;
  font-size: 0.75rem;
}

.audit-entry.latest-entry {
  border-left: 3px solid var(--emerald);
  background: #FCFDFD;
}

.leaderboard-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.leader-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.74rem;
  padding: 0.35rem 0;
  border-bottom: 1px solid var(--slate-200);
}

.gamified-badge {
  font-size: 0.62rem;
  font-weight: 700;
  padding: 0.15rem 0.45rem;
  border-radius: 6px;
  background: var(--emerald-light);
  color: var(--emerald);
  border: 1px solid var(--emerald-border);
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

/* --------------------------------------------------------------------------
   EcoSprout Mascot Container & SVG Component
   -------------------------------------------------------------------------- */
.ecosprout-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem 1rem;
  text-align: center;
  gap: 0.5rem;
}

.ecosprout-avatar {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--emerald-light), #D1FAE5);
  border: 2px solid var(--emerald-border);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 14px var(--emerald-glow);
  animation: sproutBounce 3s ease-in-out infinite;
}

.ecosprout-avatar svg {
  width: 48px;
  height: 48px;
}

.ecosprout-bubble {
  background: #FFFFFF;
  border: 1px solid var(--emerald-border);
  border-radius: 10px;
  padding: 0.45rem 0.85rem;
  font-size: 0.75rem;
  color: var(--slate-700);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  max-width: 280px;
}

@keyframes sproutBounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

/* --------------------------------------------------------------------------
   Enterprise Alert Modals
   -------------------------------------------------------------------------- */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(6px);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

.modal-overlay.hidden {
  display: none;
}

.modal-card {
  width: 520px;
  max-width: 95vw;
  background: #FFFFFF;
  border-radius: 16px;
  box-shadow: 0 20px 45px -10px rgba(0, 0, 0, 0.2);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: modalIn 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  z-index: 10001;
}

.modal-header {
  padding: 1.1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--slate-100);
}

.modal-dialog-body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.receipt-content {
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.modal-footer {
  padding: 1rem 1.5rem;
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  border-top: 1px solid var(--slate-100);
  background: #F8FAFC;
}

.receipt-item-row {
  display: flex;
  justify-content: space-between;
  font-size: 0.8rem;
  color: var(--slate-600);
}
.receipt-item-row.bold-row {
  font-weight: 700;
  color: var(--slate-900);
  border-top: 1px dashed var(--slate-300);
  padding-top: 0.5rem;
  font-size: 0.9rem;
}

.modal-stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  margin: 0.5rem 0;
}

.modal-stat-box {
  background: #F8FAFC;
  border: 1px solid var(--slate-200);
  border-radius: 10px;
  padding: 0.65rem 0.85rem;
  display: flex;
  flex-direction: column;
}
.modal-stat-box .stat-label {
  font-size: 0.65rem;
  color: var(--slate-500);
  font-family: var(--font-mono);
}
.modal-stat-box .stat-val {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--slate-900);
}

/* --------------------------------------------------------------------------
   Footer & Toasts
   -------------------------------------------------------------------------- */
.app-footer {
  padding: 1.25rem 0.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.75rem;
  color: var(--slate-500);
  border-top: 1px solid var(--slate-200);
  flex-wrap: wrap;
  gap: 0.75rem;
}

.footer-right {
  display: flex;
  gap: 1.25rem;
}

.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  z-index: 99999;
}

.toast {
  padding: 0.75rem 1.25rem;
  border-radius: 10px;
  background: #FFFFFF;
  border: 1px solid var(--slate-200);
  border-left: 4px solid var(--emerald);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.08);
  font-size: 0.8rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--slate-900);
  animation: toastIn 0.3s ease-out;
}
.toast.toast-emerald { border-left-color: var(--emerald); }
.toast.toast-blue { border-left-color: var(--electric); }
.toast.toast-rose { border-left-color: var(--rose); }
.toast.toast-amber { border-left-color: var(--amber); }

/* Utility classes */
.text-emerald { color: var(--emerald); }
.text-electric { color: var(--electric); }
.text-rose { color: var(--rose); }
.text-amber { color: var(--amber); }
.font-bold { font-weight: 700; }
.font-semibold { font-weight: 600; }
.flex { display: flex; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.max-w-\[42px\] { max-width: 42px; }

/* --------------------------------------------------------------------------
   Responsive Layout Adjustments
   -------------------------------------------------------------------------- */
@media (max-width: 1200px) {
  .view-grid-map,
  .view-grid-passengers,
  .view-grid-fleet,
  .analytics-two-col {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .app-layout {
    padding: 1rem 1rem 2rem;
  }
  .telemetry-summary-strip {
    grid-template-columns: repeat(2, 1fr);
  }
  .app-header {
    flex-direction: column;
    align-items: flex-start;
  }
  .nav-actions {
    width: 100%;
    justify-content: flex-start;
  }
}

/* Print styling for Eco-Receipt */
@media print {
  body * {
    visibility: hidden;
  }
  #receipt-modal-card,
  #receipt-modal-card * {
    visibility: visible;
  }
  #receipt-modal-card {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    box-shadow: none;
    border: 1px solid #000;
  }
  .modal-footer {
    display: none;
  }
}

@keyframes toastIn {
  from { opacity: 0; transform: translateY(15px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes modalIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}
